preConditionHook:
// Entry & Exit Confessions #28 (Two Amigos), verbatim: ADX strictly above the
// threshold and simple momentum.
// MultiWalk's WFSafe_ADX, copied statement for statement from
// AdxBelowThreshold (the bit-exact reference; EL_ADX_Probe.txt,
// scripts/adx_replica.py). Seeds at the study's first calculated bar with
// fresh Length-term DM/TR sums, followed by EMA-form updates with SF = 1/Length;
// oADX warms up as Cum(oDMI)/CurrentBar through bar Length. el_gt in the DM
// classification is decisive (near-ties from grid-price differences). No
// re-seed on a length change. The hook-scope temporaries of the reference
// (sfAdx, dmiPlus, dmiMinus, divisor, dmi) are DECLARED locals here so they
// take the placement prefix and cannot collide with AdxBelowThreshold in the
// same strategy.
adxSf = 1 / adxLength;
if (ctx.CurrentBar() == 1) {
    double sumPlusDM = 0.0;
    double sumMinusDM = 0.0;
    double sumTR = 0.0;
    for (int i = 0; i < (int)adxLength; ++i) {
        double upMove = high[i] - high[i + 1];
        double dnMove = low[i + 1] - low[i];
        double plusDM = 0.0;
        double minusDM = 0.0;
        if (el_gt(upMove, dnMove) && el_gt(upMove, 0.0)) plusDM = upMove;
        else if (el_gt(dnMove, upMove) && el_gt(dnMove, 0.0)) minusDM = dnMove;
        sumPlusDM += plusDM;
        sumMinusDM += minusDM;
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        sumTR += hi - lo;
    }
    avgPlusDM = sumPlusDM / adxLength;
    avgMinusDM = sumMinusDM / adxLength;
    volty = sumTR / adxLength;
} else {
    double upMove = high[0] - high[1];
    double dnMove = low[1] - low[0];
    double plusDM = 0.0;
    double minusDM = 0.0;
    if (el_gt(upMove, dnMove) && el_gt(upMove, 0.0)) plusDM = upMove;
    else if (el_gt(dnMove, upMove) && el_gt(dnMove, 0.0)) minusDM = dnMove;
    avgPlusDM = avgPlusDM + adxSf * (plusDM - avgPlusDM);
    avgMinusDM = avgMinusDM + adxSf * (minusDM - avgMinusDM);
    double hi = high[0] > close[1] ? high[0] : close[1];
    double lo = low[0] < close[1] ? low[0] : close[1];
    volty = volty + adxSf * ((hi - lo) - volty);
}
dmiPlus = 0.0;
dmiMinus = 0.0;
if (el_gt(volty, 0.0)) {
    dmiPlus = 100 * avgPlusDM / volty;
    dmiMinus = 100 * avgMinusDM / volty;
}
dmiDivisor = dmiPlus + dmiMinus;
dmiVal = 0.0;
if (el_gt(dmiDivisor, 0.0)) dmiVal = 100 * std::fabs(dmiPlus - dmiMinus) / dmiDivisor;
// Cum() is a series function: it accumulates every bar regardless of which
// oADX branch runs.
cumDmi = cumDmi + dmiVal;
if (ctx.CurrentBar() <= adxLength) {
    adxVal = cumDmi / ctx.CurrentBar();
} else {
    adxVal = adxVal + adxSf * (dmiVal - adxVal);
}
